<template>
  <q-dialog :model-value="modelValue" @update:model-value="$emit('update:modelValue', $event)" persistent >
    <q-card style="width: 600px; max-width: 80vw">
      <q-toolbar class="bg-primary">
        <q-toolbar-title class="text-white">
          <span v-if="isEditMode">{{ $t('user_edit') }}</span>
          <span v-else>{{ $t('add_user') }}</span>
        </q-toolbar-title>
        <f-btn icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <q-form @submit="onSubmit">
          <q-input
            dense
            outlined
            v-model="firstName"
            :label="$t('first_name')"
            class="q-mb-sm"
          />

          <q-input
            dense
            outlined
            v-model="lastName"
            :label="lastNameError || $t('last_name')"
            :error="!!lastNameError"
            class="q-mb-sm"
          />

          <q-input
            dense
            outlined
            v-model="email"
            :readonly="isEditMode"
            :label="emailError || $t('email')"
            :error="!!emailError"
            :hint="isEditMode ? $t('email_cannot_be_changed') : undefined"
            class="q-mb-sm"
          />

          <!-- Password fields (only visible when editing an existing user) -->
          <template v-if="isEditMode">
            <q-input
              dense
              outlined
              :type="showPassword ? 'text' : 'password'"
              v-model="password"
              :label="passwordError || $t('password')"
              :error="!!passwordError"
              @update:model-value="validatePasswordRules"
              class="q-mb-none"
            >
              <template v-slot:append>
                <q-icon
                  :name="showPassword ? 'visibility_off' : 'visibility'"
                  class="cursor-pointer"
                  @click="showPassword = !showPassword"
                />
              </template>
            </q-input>

            <div class="row q-mb-sm">
              <div
                v-for="(rule, index) in passwordRules"
                :key="index"
                class="display-flex v-p-5"
                :class="rule.classSpan"
              >
                <q-icon
                  :name="rule.met ? 'check_circle' : 'cancel'"
                  :color="rule.met ? 'green' : 'red'"
                  class="q-ma-xs"
                />
                <div
                  :style="{ color: rule.met ? 'green' : 'grey' }"
                  style="font-size: 14px"
                >
                  {{ rule.message }}
                </div>
              </div>
            </div>

            <q-input
              dense
              outlined
              :type="showConfirmPassword ? 'text' : 'password'"
              v-model="confirmPassword"
              :label="confirmPasswordError || $t('confirm_password')"
              :error="!!confirmPasswordError"
              class="q-mb-sm"
            >
              <template v-slot:append>
                <q-icon
                  :name="showConfirmPassword ? 'visibility_off' : 'visibility'"
                  class="cursor-pointer"
                  @click="showConfirmPassword = !showConfirmPassword"
                />
              </template>
            </q-input>
          </template>

          <!-- Account Active Toggle (only visible when editing) -->
          <div v-if="isEditMode" class="q-mb-md">
            <f-toggle
              size="xs"
              v-model="isActive"
              :label="$t('account_active')"
              color="positive"
            />
          </div>

          <div class="row q-mb-md">
            <div class="col-6">
              <q-checkbox
                v-model="role"
                :label="$t('admin_user')"
                :disable="systemAdminRole"
              />
            </div>
            <div class="col-6">
              <q-checkbox
                v-model="systemAdminRole"
                @update:model-value="handleSystemAdminChange"
                :label="$t('role_system_admin')"
              />
            </div>
          </div>

          <div class="float-right q-ml-auto q-mb-md q-mr-sm">
            <f-btn
              :label="$t('cancel')"
              appearance="cancel"
              v-close-popup
            />
            <f-btn
              :label="$t('save')"
              class="q-ml-sm"
              type="submit"
            />
          </div>
        </q-form>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref, type PropType } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { userApiService } from 'src/services';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { ApiExceptions } from 'src/exceptions';
import { dynamicObj } from 'pages/assets';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import { specialChars, passwordPattern } from 'src/constants';

export default defineComponent({
  name: 'UserFormDialog',
  mixins: [helperMixin, helperUtil],
  props: {
    modelValue: {
      type: Boolean,
      required: true,
    },
    user: {
      type: Object as PropType<Record<string, any> | null>,
      default: null,
    },
  },
  emits: ['update:modelValue', 'saved'],
  data() {
    return {
      emailError: '',
      lastNameError: '',
      passwordError: '',
      confirmPasswordError: '',
      passwordRules: [] as any[],
    };
  },
  computed: {
    isEditMode(): boolean {
      return !!this.user?.id;
    },
  },
  watch: {
    modelValue(open: boolean) {
      if (open) {
        this.populateForm();
      }
    },
  },
  methods: {
    populateForm() {
      if (this.user) {
        this.firstName = this.user.first_name || '';
        this.lastName = this.user.last_name || '';
        this.email = this.user.email || '';
        this.role = !!this.user.is_organisation_admin;
        this.systemAdminRole = !!this.user.is_system_user;
        this.isActive = this.user.is_active !== false;
      } else {
        this.firstName = '';
        this.lastName = '';
        this.email = '';
        this.role = false;
        this.systemAdminRole = false;
        this.isActive = true;
      }
      this.password = '';
      this.confirmPassword = '';
      this.showPassword = false;
      this.showConfirmPassword = false;
      this.emailError = '';
      this.lastNameError = '';
      this.passwordError = '';
      this.confirmPasswordError = '';
      this.preparePasswordRules();
    },
    preparePasswordRules() {
      this.passwordRules = [
        {
          message: this.$t('password_length'),
          test: (pw: string) => pw.length >= 8,
          met: false,
          classSpan: 'col-6',
        },
        {
          message: this.$t('password_lowercase'),
          test: (pw: string) => /[a-z]/.test(pw),
          met: false,
          classSpan: 'col-6',
        },
        {
          message: this.$t('password_uppercase'),
          test: (pw: string) => /[A-Z]/.test(pw),
          met: false,
          classSpan: 'col-6',
        },
        {
          message: this.$t('password_number'),
          test: (pw: string) => /\d/.test(pw),
          met: false,
          classSpan: 'col-6',
        },
        {
          message: this.$t('one_special_char_minimum', { chars: specialChars }),
          test: (pw: string) => new RegExp(`[${specialChars}]`).test(pw),
          met: false,
          classSpan: 'col-12',
        },
      ];
    },
    validatePasswordRules() {
      this.passwordRules.forEach((rule: any) => {
        rule.met = rule.test(this.password);
      });
    },
    onSubmit() {
      this.lastNameError = '';
      this.emailError = '';
      this.passwordError = '';
      this.confirmPasswordError = '';

      if (!this.validateEmail(this.email)) {
        this.emailError = this.$t('invalid_email');
      }

      if (!this.lastName || this.lastName.trim() === '') {
        this.lastNameError = this.$t('last_name_required');
      }

      // Validate password only in edit mode and only if user entered something
      if (this.isEditMode && (this.password || this.confirmPassword)) {
        if (!passwordPattern.test(this.password)) {
          this.passwordError = this.$t('password_is_invalid');
        }
        if (!passwordPattern.test(this.confirmPassword)) {
          this.confirmPasswordError = this.$t('confirm_password_is_invalid');
        }
        if (this.password !== this.confirmPassword) {
          this.confirmPasswordError = this.$t('password_not_match');
        }
      }

      if (this.emailError || this.lastNameError || this.passwordError || this.confirmPasswordError) {
        return;
      }

      this.saveUser();
    },
    async saveUser() {
      const data: Record<string, any> = {
        first_name: this.firstName,
        last_name: this.lastName,
        email: this.email,
        org_id: getOrgId(),
        is_system_user: this.systemAdminRole,
      };

      const isEdit = this.isEditMode;
      const roleKey = isEdit ? 'is_organisation_admin' : 'is_admin';
      data[roleKey] = this.role;

      if (isEdit) {
        data['is_active'] = this.isActive;
        // Only include password if it was actually changed
        if (this.password && this.password.trim().length > 0) {
          data.password = this.password;
        }
      }

      const formData = new FormData();
      Object.entries(data).forEach(([key, value]) => {
        formData.append(key, value != null ? String(value) : '');
      });

      this.showLoading();

      try {
        const response = isEdit
          ? await userApiService.editUser(this.user!.id!, formData)
          : await userApiService.addUser(formData);

        if (response?.success === false) {
          throw response;
        }

        notify.success(
          isEdit
            ? this.$t('user_updated')
            : this.$t('user_successfully_created'),
        );

        this.$emit('update:modelValue', false);
        this.$emit('saved');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async handleSystemAdminChange(val: boolean) {
      if (val) {
        try {
          const exists = await userApiService.checkIfSystemAdminExists(
            this.isEditMode ? this.user?.id : null,
          );
          if (exists) {
            notify.error(this.$t('error_msg_system_admin_exists'));
            this.systemAdminRole = false;
            this.role = false;
            return;
          }
          this.role = true;
        } catch (error) {
          const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
          notify.error(msg);
          logError(error);
        }
      }
    },
  },
  setup() {
    return {
      role: ref(false),
      systemAdminRole: ref(false),
      isActive: ref(true),
      email: ref(''),
      firstName: ref(''),
      lastName: ref(''),
      password: ref(''),
      confirmPassword: ref(''),
      showPassword: ref(false),
      showConfirmPassword: ref(false),
    };
  },
});
</script>
